draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // stranger
  ctx.fillStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W * 0.8, H * 0.5, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W * 0.8, H * 0.5 + 20);
  ctx.lineTo(W * 0.8, H * 0.5 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W * 0.8, H * 0.5 + 50);
  ctx.lineTo(W * 0.8 - 20, H * 0.5 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W * 0.8, H * 0.5 + 50);
  ctx.lineTo(W * 0.8 + 20, H * 0.5 + 70);
  ctx.stroke();

  // dog
  ctx.fillStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W * 0.2 + 50 * Math.sin(t), H * 0.5, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W * 0.2 + 50 * Math.sin(t), H * 0.5 + 20);
  ctx.lineTo(W * 0.2 + 50 * Math.sin(t), H * 0.5 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W * 0.2 + 50 * Math.sin(t), H * 0.5 + 50);
  ctx.lineTo(W * 0.2 + 50 * Math.sin(t) - 20, H * 0.5 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W * 0.2 + 50 * Math.sin(t), H * 0.5 + 50);
  ctx.lineTo(W * 0.2 + 50 * Math.sin(t) + 20, H * 0.5 + 70);
  ctx.stroke();

  ctx.restore();
}
